use std::{
    collections::{BTreeMap, BTreeSet},
    env,
    error::Error,
    fs,
};

use ga_domain::file_import::{FileFieldInput, FileMapping};
use serde_json::{Value, json};

#[test]
#[ignore = "requires the synthetic file value decisions generated by pinned Python"]
fn matches_pinned_file_values_and_timestamps() -> Result<(), Box<dyn Error>> {
    let cases: Vec<Value> = serde_json::from_slice(&fs::read(env::var("GA_TEST_FILE_VALUES")?)?)?;
    let mut tested = 0;
    for case in cases {
        let mapping = FileMapping::from_json(&serde_json::to_vec(&case["mapping"])?)?;
        let kind = match case["kind"].as_str() {
            Some("boolean") => FileFieldInput::Boolean,
            Some("integer") => FileFieldInput::Integer,
            Some("number") => FileFieldInput::Number,
            Some("json") => FileFieldInput::Complex,
            Some("text") => FileFieldInput::Text,
            _ => return Err("Unknown synthetic field kind".into()),
        };
        let fields = BTreeMap::from([("field", kind)]);
        let rows = mapping.read_rows(
            case["data"]
                .as_str()
                .ok_or("Missing synthetic data")?
                .as_bytes(),
        )?;
        let expected = case["outcomes"]
            .as_array()
            .ok_or("Missing expected decisions")?;
        assert_eq!(rows.len(), expected.len());
        let mut seen = BTreeSet::new();
        for (index, (row, expected)) in rows.iter().zip(expected).enumerate() {
            let actual = match mapping.map_row(row, &fields, &mut seen) {
                Ok(mapped) => json!({
                    "id":mapped.source_id,"start":mapped.start.unix_microseconds(),
                    "end":mapped.end.map(ga_domain::timestamp::StoredInstant::unix_microseconds),
                    "values":mapped.values,"units":mapped.units,
                }),
                Err(issue) => json!({"code":issue.code,"field":issue.field}),
            };
            assert_eq!(actual, *expected, "{} row {}", case["label"], index + 1);
            tested += 1;
        }
    }
    assert!(tested > 200);
    println!("Matched {tested} typed import row decisions");
    Ok(())
}
